# Per-species gun ALCARECO config: Pion
# Auto-generated by mk_alca_cfgs.py (MuKPiGun_UL16_Premix_e2e_v1).
# Policy (2026-10-16): no HLT/DCS prefilters, NO track cuts (passthrough).
# Keeps the gen-matched tracks with their extras/hits/clusters, the MC truth
# needed for the gen and sim-hit association of the track refit (genParticles,
# generator, slimmed pileup, SimTracks/SimVertices, tracker PSimHits) and the muons
# linked to the gen-matched tracks.
import FWCore.ParameterSet.Config as cms

from Configuration.Eras.Era_Run2_2016_cff import Run2_2016

process = cms.Process("ALCA", Run2_2016)

process.load("Configuration.StandardSequences.Services_cff")
process.load("FWCore.MessageService.MessageLogger_cfi")
process.load("Configuration.EventContent.EventContent_cff")
process.load("Configuration.StandardSequences.GeometryRecoDB_cff")
process.load("Configuration.StandardSequences.MagneticField_cff")
process.load("Configuration.StandardSequences.FrontierConditions_GlobalTag_cff")

import Alignment.CommonAlignmentProducer.AlignmentTrackSelector_cfi as _ats

process.maxEvents = cms.untracked.PSet(input=cms.untracked.int32(-1))

process.source = cms.Source(
    "PoolSource",
    fileNames=cms.untracked.vstring("file:step4_RECO.root"),
    secondaryFileNames=cms.untracked.vstring(),
)

# ---------------- selection: passthrough (quality-free) ----------------
process.ALCARECOPion = _ats.AlignmentTrackSelector.clone(
    src = "generalTracks",
    filter = True,
    applyBasicCuts = False,
)

# ------- loose gen-match SELECTOR (dR<=0.3): keeps the matched tracks with their
# stock clone family (extras + owned hits + clusters) and, with filter=True,
# drops events in which nothing matched. filter is NOT optional: ObjectSelector
# defaults filter_ to false and only reads the parameter when a bool of that name
# is present in the PSet, so omitting it silently keeps pure-pileup events. -------
process.genMatchedTracks = cms.EDFilter(
    "GenMatchedTrackSelectorModule",
    src = cms.InputTag("ALCARECOPion"),
    genParticles = cms.InputTag("genParticles"),
    dRMatchMax = cms.double(0.3),
    dPtRelMatchMax = cms.double(1.0),
    genMinPt = cms.double(0.0),
    genMaxAbsEta = cms.double(3.0),
    filter = cms.bool(True),
)

# ------- muons whose inner track is a gen-matched track, with innerTrack
# re-pointed to genMatchedTracks and the standalone/global/TeV-refit tracks
# cloned alongside (the full muons collection refers to generalTracks etc.,
# which are not kept). Also writes the track -> muon association. -------
from Alignment.AlCaRecoMuons.AlCaRecoMuonRelinker_cfi import AlCaRecoMuonRelinker
process.genMatchedMuons = AlCaRecoMuonRelinker.clone(
    muons = "muons",
    selectedTracks = "genMatchedTracks",
)

# ------- pileup summary slimmed as in MiniAOD (the full PileupSummaryInfos are
# ~3.7 kB/event each under premixing, and there are two copies: addPileupInfo
# and mixData) -------
from PhysicsTools.PatAlgos.slimming.slimmedAddPileupInfo_cfi import slimmedAddPileupInfo
process.slimmedAddPileupInfo = slimmedAddPileupInfo.clone()

process.seqALCARECOPion = cms.Sequence(process.ALCARECOPion * process.genMatchedTracks * process.genMatchedMuons * process.slimmedAddPileupInfo)
process.pathALCARECOPion = cms.Path(process.seqALCARECOPion)

# --------------------------- output -----------------------------
process.ALCARECOStreamPion = cms.OutputModule(
    "PoolOutputModule",
    SelectEvents=cms.untracked.PSet(SelectEvents=cms.vstring("pathALCARECOPion")),
    dataset=cms.untracked.PSet(
        dataTier=cms.untracked.string("ALCARECO"),
        filterName=cms.untracked.string("Pion"),
    ),
    eventAutoFlushCompressedSize=cms.untracked.int32(5242880),
    fileName=cms.untracked.string("Pion.root"),
    outputCommands=cms.untracked.vstring(
        "drop *",
        "drop recoTracks_ALCARECOPion_*_*",
        "drop recoTracks_generalTracks_*_*",
        "keep *_genMatchedTracks_*_*",
        "keep *_genParticles_*_*",
        "keep GenRunInfoProduct_generator_*_*",
        "keep GenLumiInfoHeader_generator_*_*",
        "keep GenLumiInfoProduct_generator_*_*",
        "keep GenEventInfoProduct_generator_*_*",
        "keep *_slimmedAddPileupInfo_*_*",
        "keep int_*_bunchSpacing_*",
        "keep SimTracks_g4SimHits_*_*",
        "keep SimVertexs_g4SimHits_*_*",
        "keep PSimHits_g4SimHits_TrackerHits*_*",
        "keep *_genMatchedMuons_*_*",
        "keep *_offlineBeamSpot_*_*",
        "keep *_offlinePrimaryVertices_*_*",
        "keep L1AcceptBunchCrossings_*_*_*",
        "keep L1GlobalTriggerReadoutRecord_gtDigis_*_*",
        "keep *_TriggerResults_*_*",
        "keep DcsStatuss_scalersRawToDigi_*_*",
    ),
)
process.ALCARECOStreamPionOutPath = cms.EndPath(process.ALCARECOStreamPion)

# ------------------------ conditions ------------------------
from Configuration.AlCa.GlobalTag import GlobalTag
process.GlobalTag = GlobalTag(process.GlobalTag, "106X_mcRun2_asymptotic_v13", "")

process.schedule = cms.Schedule(process.pathALCARECOPion, process.ALCARECOStreamPionOutPath)

# resource-policy align to 8-core jobs (2026-10-19)
if not hasattr(process, "options"): process.options = cms.untracked.PSet()
process.options.numberOfThreads = cms.untracked.uint32(4)

# final-leg framework-job-report for CRAB wrappers (produces FrameworkJobReport.xml)
from Configuration.DataProcessing.Utils import addMonitoring
process = addMonitoring(process)
